package com.farika.soundflow;
import android.content.Context;import android.graphics.*;import android.view.*;import android.view.accessibility.*;
/** Touch coordinates are vertical, not a rotated horizontal hit target. */
final class VerticalFader extends View {
 interface Changed{void value(int gain);}private int gain;private final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);private final Changed changed;private final String label;
 VerticalFader(Context c,String label,int value,Changed changed){super(c);this.label=label;this.changed=changed;gain=value;setFocusable(true);setClickable(true);updateDescription();}
 int gain(){return gain;}void gain(int g){gain=Math.max(-1200,Math.min(1200,g));updateDescription();invalidate();}
 private void updateDescription(){setContentDescription(label+", "+String.format(java.util.Locale.US,"%+.1f дБ",gain/100f));}
 protected void onDraw(Canvas c){super.onDraw(c);float x=getWidth()/2f,pad=SoundFlowUi.dp(getContext(),18),top=pad,bottom=getHeight()-pad,y=bottom-(gain+1200)/2400f*(bottom-top);paint.setStrokeWidth(SoundFlowUi.dp(getContext(),4));paint.setStrokeCap(Paint.Cap.ROUND);paint.setColor(SoundFlowUi.RAISED);c.drawLine(x,top,x,bottom,paint);paint.setColor(isEnabled()?SoundFlowUi.ACCENT:SoundFlowUi.MUTED);c.drawLine(x,(top+bottom)/2,x,y,paint);paint.setStrokeWidth(1);c.drawLine(x-9,(top+bottom)/2,x+9,(top+bottom)/2,paint);c.drawCircle(x,y,SoundFlowUi.dp(getContext(),9),paint);}
 private void change(int value){gain(value);changed.value(gain);sendAccessibilityEvent(AccessibilityEvent.TYPE_VIEW_SELECTED);}
 public boolean onTouchEvent(android.view.MotionEvent e){if(!isEnabled())return false;if(e.getActionMasked()==android.view.MotionEvent.ACTION_DOWN||e.getActionMasked()==android.view.MotionEvent.ACTION_MOVE||e.getActionMasked()==android.view.MotionEvent.ACTION_UP){getParent().requestDisallowInterceptTouchEvent(true);float pad=SoundFlowUi.dp(getContext(),18),span=Math.max(1,getHeight()-2*pad);change(Math.round(((getHeight()-pad-e.getY())/span*2400-1200)/100f)*100);if(e.getActionMasked()==android.view.MotionEvent.ACTION_UP){performClick();getParent().requestDisallowInterceptTouchEvent(false);}return true;}if(e.getActionMasked()==android.view.MotionEvent.ACTION_CANCEL){getParent().requestDisallowInterceptTouchEvent(false);return true;}return true;}
 public boolean performClick(){super.performClick();return true;}
 public boolean onKeyDown(int code,android.view.KeyEvent e){if(isEnabled()&&(code==android.view.KeyEvent.KEYCODE_DPAD_UP||code==android.view.KeyEvent.KEYCODE_DPAD_DOWN)){change(gain+(code==android.view.KeyEvent.KEYCODE_DPAD_UP?100:-100));return true;}return super.onKeyDown(code,e);}
 public void onInitializeAccessibilityNodeInfo(AccessibilityNodeInfo info){super.onInitializeAccessibilityNodeInfo(info);info.setClassName("android.widget.SeekBar");info.setRangeInfo(AccessibilityNodeInfo.RangeInfo.obtain(AccessibilityNodeInfo.RangeInfo.RANGE_TYPE_INT,-1200,1200,gain));info.addAction(AccessibilityNodeInfo.AccessibilityAction.ACTION_SCROLL_FORWARD);info.addAction(AccessibilityNodeInfo.AccessibilityAction.ACTION_SCROLL_BACKWARD);}
 public boolean performAccessibilityAction(int action,android.os.Bundle args){if(isEnabled()&&(action==AccessibilityNodeInfo.ACTION_SCROLL_FORWARD||action==AccessibilityNodeInfo.ACTION_SCROLL_BACKWARD)){change(gain+(action==AccessibilityNodeInfo.ACTION_SCROLL_FORWARD?100:-100));return true;}return super.performAccessibilityAction(action,args);}
}
